"""Offline chunk + embed pipeline (not on the serving path).

Used by the CI vector-index build and the evaluator.
The copilot's serving path does **not** import this.
"""

from typing import Any, Dict, Iterable, List

import structlog

from rasa.builder.document_retrieval.local.chunking import Chunk, Chunker
from rasa.builder.document_retrieval.local.config import (
    LocalRetrievalConfig,
    SearchMode,
)
from rasa.builder.document_retrieval.local.embedding import Embedder
from rasa.builder.document_retrieval.local.index import (
    _index_key,
    _stamped_corpus_version,
    _table_dir,
    _write_meta,
)
from rasa.builder.document_retrieval.local.vector_store import BaseVectorStore
from rasa.builder.document_retrieval.source import ContentType, SourceDocument

structlogger = structlog.get_logger()


def _build_chunks(
    documents: Iterable[SourceDocument], cfg: LocalRetrievalConfig
) -> List[Chunk]:
    """Chunk every document with its content-type profile, tagging the topic."""
    chunkers: Dict[ContentType, Chunker] = {}
    chunks: List[Chunk] = []
    for document in documents:
        content_type = document.content_type
        if content_type not in chunkers:
            chunkers[content_type] = Chunker(cfg.chunking_for(content_type))
        # Topic is corpus-provided metadata
        topic = str(document.metadata.get("topic", ""))
        chunks.extend(chunkers[content_type].chunk_document(document, topic))
    return chunks


def build_chunk_rows(
    documents: List[SourceDocument], cfg: LocalRetrievalConfig, embedder: Embedder
) -> List[Dict[str, Any]]:
    """Chunk + embed the given documents."""
    chunks = _build_chunks(documents, cfg)
    if not chunks:
        return []
    vectors = embedder.encode([c.text for c in chunks])
    return [
        {
            "vector": vectors[i],
            "text": c.text,
            "doc_id": c.doc_id,
            "url": c.url,
            "title": c.title,
            "topic": c.topic,
            "version": c.version,
            "chunk_index": c.chunk_index,
        }
        for i, c in enumerate(chunks)
    ]


def sync_index(
    store: BaseVectorStore,
    cfg: LocalRetrievalConfig,
    documents: List[SourceDocument],
    corpus_version: str,
    embedder: Embedder,
) -> None:
    """Build ``store`` from ``documents`` (embeds here).

    Required for evaluator, might be refactored in future.

    Args:
        store: The vector store to populate.
        cfg: Local retrieval configuration.
        documents: The full corpus (whole documents; chunked here).
        corpus_version: Opaque snapshot id; stamped into the index metadata.
        embedder: Embedder used to vectorize chunks (shared with the retriever).
    """
    if not documents:
        raise ValueError("Cannot build an index from an empty document set.")

    key = _index_key(cfg)
    table_dir = _table_dir(cfg)

    if store.exists() and _stamped_corpus_version(table_dir) == corpus_version:
        structlogger.info(
            "local_index.build_noop", key=key, document_count=len(documents)
        )
        return

    if store.exists():
        store.drop()

    rows = build_chunk_rows(documents, cfg, embedder)
    if not rows:
        raise ValueError(f"No chunks produced from {len(documents)} source documents.")
    store.add(rows)
    # FTS index backs hybrid search only; skip the build cost when serving vector.
    if cfg.search_mode is SearchMode.HYBRID:
        store.ensure_text_index()
    _write_meta(table_dir, cfg, embedder.dim, corpus_version, len(documents), len(rows))
    structlogger.info(
        "local_index.built",
        key=key,
        document_count=len(documents),
        chunk_count=len(rows),
        embed_dim=embedder.dim,
    )
